const originalProductCatalog = new Map();

function sanitizeText(value, maxLength = 500) {
  if (value === null || value === undefined) return '';
  const stringValue = String(value)
    .replace(/[\u0000-\u001F\u007F]/g, '')
    .replace(/<script|<iframe|javascript:|onerror=|onload=/gi, '')
    .trim();
  return stringValue.slice(0, maxLength);
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function isValidEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value || '').trim());
}

function isValidPhone(value) {
  const normalized = String(value || '').replace(/\s+/g, '');
  return /^\+?[0-9]{8,15}$/.test(normalized);
}

window.sanitizeText = sanitizeText;
window.escapeHtml = escapeHtml;
window.isValidEmail = isValidEmail;
window.isValidPhone = isValidPhone;

function captureOriginalProductCatalog() {
  document.querySelectorAll('.card-link').forEach(card => {
    const btn = card.querySelector('.add-to-cart-btn');
    const productId = btn?.dataset.id;
    if (!productId || originalProductCatalog.has(productId)) return;

    const titleEl = card.querySelector('h3');
    const descEl = card.querySelector('p');
    originalProductCatalog.set(productId, {
      title: titleEl ? titleEl.textContent.trim() : '',
      description: descEl ? descEl.textContent.trim() : '',
      button: btn ? btn.textContent.replace(/^🛒\s*/, '').trim() : 'Add to cart',
      dataName: btn?.dataset.name || '',
      category: btn?.dataset.cat || ''
    });
  });
}

function applyProductCatalogLanguage(lang) {
  document.querySelectorAll('.card-link').forEach(card => {
    const btn = card.querySelector('.add-to-cart-btn');
    const productId = btn?.dataset.id;
    if (!productId) return;

    const titleEl = card.querySelector('h3');
    const descEl = card.querySelector('p');
    const original = originalProductCatalog.get(productId);

    if (lang === 'vi' && original) {
      if (titleEl) titleEl.textContent = original.title;
      if (descEl) descEl.textContent = original.description;
      if (btn) {
        btn.textContent = '🛒 ' + original.button;
        btn.dataset.name = original.dataName;
        if (original.category) btn.dataset.cat = original.category;
      }
      return;
    }

    const entry = productCatalogTranslations[productId];
    if (!entry) return;

    if (titleEl) titleEl.textContent = entry.title;
    if (descEl) descEl.textContent = entry.description;
    if (btn) {
      btn.textContent = '🛒 ' + entry.button;
      btn.dataset.name = entry.dataName;
      if (entry.category) btn.dataset.cat = entry.category;
    }
  });
}

