// Share helpers: delegated handler for .share-btn buttons
function openShareWindow(url, name, opts) {
  window.open(url, name, opts || "noopener,noreferrer,width=600,height=420");
}

function handleShareClick(e) {
  const btn = e.target.closest('.share-btn');
  if (!btn) return;
  const action = btn.dataset.action;
  const shareUrl = btn.dataset.url || window.location.href;
  const title = btn.dataset.title || document.title;
  const text = btn.dataset.text || title;

  if (action === 'native' && navigator.share) {
    navigator.share({ title, text, url: shareUrl }).catch(()=>{});
    return;
  }

  if (action === 'facebook') {
    openShareWindow('https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(shareUrl), 'fbshare');
    return;
  }

  if (action === 'twitter') {
    openShareWindow('https://twitter.com/intent/tweet?text=' + encodeURIComponent(text) + '&url=' + encodeURIComponent(shareUrl), 'twshare');
    return;
  }

  if (action === 'copy') {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(shareUrl).then(() => {
        alert('Đã sao chép liên kết');
      }).catch(() => { alert('Không thể sao chép'); });
    } else {
      try { window.prompt('Sao chép liên kết:', shareUrl); } catch { /* noop */ }
    }
    return;
  }
}

document.addEventListener('click', handleShareClick);

