/* Mark current nav link active based on pathname (including products submenu) */
function setActiveNav() {
  const links = document.querySelectorAll('.site-nav a');
  const currentFile = (window.location.pathname.split('/').pop() || 'index.html').toLowerCase();
  links.forEach(a => {
    const href = (a.getAttribute('href') || '').split('?')[0].split('/').pop().toLowerCase();
    if (!href) return;
    if (href === currentFile || (currentFile === '' && (href === 'index.html' || href === ''))) {
      a.classList.add('active');
      const submenuToggle = a.closest('.submenu')?.parentElement?.querySelector('.submenu-toggle');
      if (submenuToggle) submenuToggle.classList.add('active');
    }
    // products page should highlight submenu toggle
    if (currentFile === 'products.html' && (href === 'products.html')) {
      a.classList.add('active');
      a.closest('.has-submenu')?.querySelector('.submenu-toggle')?.classList.add('active');
    }
  });
}

setActiveNav();

// Keep the products submenu open while moving the pointer from the menu item into the submenu itself.
document.querySelectorAll('.has-submenu').forEach(menu => {
  const toggle = menu.querySelector('.submenu-toggle');
  const submenu = menu.querySelector('.submenu');
  if (!toggle || !submenu) return;

  const openMenu = () => menu.classList.add('open');
  const closeMenu = () => {
    if (!menu.matches(':hover') && !menu.contains(document.activeElement)) {
      menu.classList.remove('open');
    }
  };

  menu.addEventListener('mouseenter', openMenu);
  menu.addEventListener('mouseleave', closeMenu);
  submenu.addEventListener('mouseenter', openMenu);
  submenu.addEventListener('mouseleave', closeMenu);
  toggle.addEventListener('focus', openMenu);
  toggle.addEventListener('blur', (event) => {
    const next = event.relatedTarget;
    if (!menu.contains(next)) closeMenu();
  });
  submenu.querySelectorAll('a').forEach(link => {
    link.addEventListener('focus', openMenu);
    link.addEventListener('blur', (event) => {
      const next = event.relatedTarget;
      if (!menu.contains(next)) closeMenu();
    });
  });
});

/* Page navigation fade: intercept internal link clicks and fade out before navigating */
document.addEventListener('click', (e) => {
  const a = e.target.closest('a');
  if (!a) return;
  const href = a.getAttribute('href');
  if (!href) return;
  // ignore external links, anchors, mailto, tel, and links with target
  if (href.startsWith('http') && !href.includes(window.location.origin)) return;
  if (href.startsWith('mailto:') || href.startsWith('tel:')) return;
  if (href.startsWith('#')) return; // allow in-page anchors
  if (a.target && a.target !== '' && a.target !== '_self') return;

  // only intercept same-origin navigation
  // Normalize root-absolute paths ("/index.html") to relative paths when running file:// or non-root contexts
  let interceptHref = href;
  if (interceptHref.startsWith('/')) {
    interceptHref = interceptHref.replace(/^\/+/, '');
  }
  const url = new URL(interceptHref, window.location.href);
  if (url.origin !== window.location.origin) return;

  // let downloads go through (has download attribute)
  if (a.hasAttribute('download')) return;

  // perform fade and navigate
  e.preventDefault();
  document.body.classList.add('page-exit');
  setTimeout(() => { window.location.href = url.href; }, 320);
});

/* Products filtering: apply filters based on query params and UI clicks */
function applyProductFilter() {
  const list = document.querySelectorAll('.card-link');
  const params = new URLSearchParams(window.location.search);
  const cat = (params.get('cat') || '').toLowerCase();
  const filter = (params.get('filter') || '').toLowerCase();

  // also allow simple UI with data-filter
  const activeFilterBtn = document.querySelector('.product-filters button.active');
  const uiFilter = activeFilterBtn?.dataset?.filter || '';

  list.forEach(a => {
    const itemCat = (a.dataset.category || '').toLowerCase();
    const tags = (a.dataset.tags || '').toLowerCase();
    let show = true;

    if (cat) {
      show = itemCat === cat;
    }
    const effectiveFilter = filter || uiFilter;
    if (effectiveFilter && effectiveFilter !== 'all') {
      if (effectiveFilter === 'new') show = show && tags.split(',').includes('new');
      if (effectiveFilter === 'best') show = show && tags.split(',').includes('best');
    }

    if (show) a.classList.remove('hidden'); else a.classList.add('hidden');
  });
}

// wire product filter buttons
document.querySelectorAll('.product-filters button').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.product-filters button').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    // update URL param without reload
    const f = btn.dataset.filter;
    const url = new URL(window.location.href);
    if (f && f !== 'all') url.searchParams.set('filter', f); else url.searchParams.delete('filter');
    // push state
    window.history.replaceState({}, '', url);
    applyProductFilter();
  });
});

// Set initial active filter button from URL param (if present), otherwise default UI
