const initialFilter = initialParams.get('filter');
if (initialFilter) {
  const btn = document.querySelector(`.product-filters button[data-filter="${initialFilter}"]`);
  if (btn) {
    document.querySelectorAll('.product-filters button').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
  }
}

