// Load content index (thumbnails, excerpts) and auto-fill listing cards
fetch('content.json').then(r => r.ok ? r.json() : null).then(content => {
  if (!content) return;
  const allItems = (content.posts || []).concat(content.products || []);
  document.querySelectorAll('.card-link').forEach(a => {
    try {
      const href = a.getAttribute('href');
      const match = allItems.find(it => it.url === href || it.id === href.replace('.html',''));
      if (!match) return;
      // set thumbnail
      const imgEl = a.querySelector('.card-image');
      if (imgEl) {
        imgEl.style.backgroundImage = `linear-gradient(180deg, rgba(195,107,24,0.12), rgba(121,61,21,0.16)), url('${match.image}')`;
      }
      // set title and excerpt if missing
      const titleEl = a.querySelector('h3');
      const pEl = a.querySelector('p');
      if (titleEl && (!titleEl.textContent || titleEl.textContent.trim().length===0)) titleEl.textContent = match.title;
      if (pEl && (!pEl.textContent || pEl.textContent.trim().length===0)) pEl.textContent = match.excerpt;
      // attach data for preview/share
      a.dataset.title = match.title;
      a.dataset.excerpt = match.excerpt;
      a.dataset.image = match.image;
      a.dataset.canonical = (content.siteBase || '') + match.url;
    } catch (e) { /* ignore */ }
  });

  // enhance listing read-more / preview: show tooltip preview on hover for card-link
  let previewTimer = null;
  const previewBox = document.createElement('div');
  previewBox.className = 'card-preview-box';
  previewBox.style.position='fixed'; previewBox.style.zIndex='9999'; previewBox.style.display='none'; previewBox.style.maxWidth='320px'; previewBox.style.background='#fff'; previewBox.style.border='1px solid rgba(0,0,0,0.06)'; previewBox.style.boxShadow='0 8px 30px rgba(0,0,0,0.12)'; previewBox.style.padding='10px'; previewBox.style.borderRadius='10px';
  document.body.appendChild(previewBox);

  const renderPreviewCard = (match, event) => {
    previewBox.textContent = '';
    previewBox.style.display = 'block';
    previewBox.style.left = (event.clientX + 12) + 'px';
    previewBox.style.top = (event.clientY + 12) + 'px';

    const wrap = document.createElement('div');
    wrap.style.display = 'flex';
    wrap.style.gap = '10px';

    const thumb = document.createElement('div');
    thumb.style.width = '110px';
    thumb.style.height = '70px';
    thumb.style.backgroundImage = `url('${escapeHtml(match.image || '')}')`;
    thumb.style.backgroundSize = 'cover';
    thumb.style.borderRadius = '8px';

    const info = document.createElement('div');
    const title = document.createElement('strong');
    title.textContent = match.title || '';
    const excerpt = document.createElement('p');
    excerpt.style.margin = '6px 0';
    excerpt.style.color = '#6f4e32';
    excerpt.textContent = match.excerpt || '';

    info.appendChild(title);
    info.appendChild(excerpt);
    wrap.appendChild(thumb);
    wrap.appendChild(info);
    previewBox.appendChild(wrap);
  };

  document.querySelectorAll('.card-link').forEach(a=>{
    a.addEventListener('mouseenter', (ev)=>{
      const match = allItems.find(it => it.url === a.getAttribute('href'));
      if (!match) return;
      previewTimer = setTimeout(()=> renderPreviewCard(match, ev), 280);
    });
    a.addEventListener('mouseleave', ()=>{
      if (previewTimer) clearTimeout(previewTimer);
      previewBox.style.display='none';
    });
  });

  // preview modal for share buttons
  const modal = document.createElement('div');
  modal.className='preview-modal';
  modal.style.position='fixed'; modal.style.inset='0'; modal.style.display='none'; modal.style.alignItems='center'; modal.style.justifyContent='center'; modal.style.background='rgba(0,0,0,0.45)'; modal.style.zIndex='10000';

  const modalCard = document.createElement('div');
  modalCard.style.background='#fff';
  modalCard.style.borderRadius='12px';
  modalCard.style.maxWidth='900px';
  modalCard.style.padding='18px';
  modalCard.style.boxShadow='0 20px 60px rgba(0,0,0,0.25)';

  const closeBtn = document.createElement('button');
  closeBtn.type = 'button';
  closeBtn.className = 'preview-close';
  closeBtn.style.float = 'right';
  closeBtn.style.background = '#fff';
  closeBtn.style.border = '0';
  closeBtn.style.fontSize = '18px';
  closeBtn.style.cursor = 'pointer';
  closeBtn.textContent = '✕';
  closeBtn.addEventListener('click', ()=> modal.style.display='none');

  const previewContent = document.createElement('div');
  previewContent.className = 'preview-content';

  modalCard.appendChild(closeBtn);
  modalCard.appendChild(previewContent);
  modal.appendChild(modalCard);
  document.body.appendChild(modal);

  document.addEventListener('click', (e)=>{
    const btn = e.target.closest('.share-btn');
    if (!btn) return;
    if (btn.dataset.action === 'preview') {
      const root = btn.closest('article') || btn.closest('body');
      const href = root.querySelector && root.querySelector('a.card-link') ? root.querySelector('a.card-link').getAttribute('href') : null;
      const entry = allItems.find(it => it.url === href) || allItems.find(it => it.url === window.location.pathname.split('/').pop());
      const previewContent = modal.querySelector('.preview-content');
      if (entry) {
        previewContent.textContent = '';

        const wrap = document.createElement('div');
        wrap.style.display = 'flex';
        wrap.style.gap = '18px';

        const imageWrap = document.createElement('div');
        imageWrap.style.flex = '0 0 260px';

        const img = document.createElement('img');
        img.src = entry.image || '';
        img.alt = entry.title || 'Preview image';
        img.style.width = '100%';
        img.style.borderRadius = '8px';
        imageWrap.appendChild(img);

        const body = document.createElement('div');
        body.style.flex = '1';

        const h2 = document.createElement('h2');
        h2.textContent = entry.title || '';

        const p = document.createElement('p');
        p.style.color = '#6f4e32';
        p.textContent = entry.excerpt || '';

        const linkRow = document.createElement('p');
        linkRow.style.marginTop = '12px';

        const link = document.createElement('a');
        link.href = entry.url || '#';
        link.className = 'button';
        link.textContent = 'Xem trang';

        linkRow.appendChild(link);
        body.appendChild(h2);
        body.appendChild(p);
        body.appendChild(linkRow);

        wrap.appendChild(imageWrap);
        wrap.appendChild(body);
        previewContent.appendChild(wrap);
      } else {
        previewContent.textContent = 'Không tìm thấy nội dung để xem trước.';
      }
      modal.style.display='flex';
    }
  });

  const signupTrigger = document.getElementById('signupTrigger');
  const signupModal = document.getElementById('signupModal');
  const signupClose = signupModal?.querySelector('.modal-close');
  const cancelSignup = document.getElementById('cancelSignup');
  const signupForm = document.getElementById('signupForm');
  const signupResponse = document.getElementById('signupResponse');
  const downloadNav = document.getElementById('downloadNav');
  const downloadLink = document.getElementById('downloadLink');
  const downloadModal = document.getElementById('downloadModal');
  const downloadClose = downloadModal?.querySelector('.modal-close');
  const cancelDownload = document.getElementById('cancelDownload');
  const downloadForm = document.getElementById('downloadForm');
  const downloadResponse = document.getElementById('downloadResponse');

  const closeSignup = () => {
    if (signupModal) {
      signupModal.classList.remove('active');
    }
    if (signupResponse) {
      signupResponse.textContent = '';
    }
    signupForm?.reset();
  };

  const closeDownload = () => {
    if (downloadModal) {
      downloadModal.classList.remove('active');
    }
    if (downloadResponse) {
      downloadResponse.textContent = '';
    }
    downloadForm?.reset();
  };

  signupTrigger?.addEventListener('click', () => {
    signupModal.classList.add('active');
  });

  signupClose?.addEventListener('click', closeSignup);
  cancelSignup?.addEventListener('click', closeSignup);

  signupModal?.addEventListener('click', (event) => {
    if (event.target === signupModal) closeSignup();
  });

  downloadNav?.addEventListener('click', (event) => {
    event.preventDefault();
    downloadModal.classList.add('active');
  });

  downloadLink?.addEventListener('click', (event) => {
    event.preventDefault();
    downloadModal.classList.add('active');
  });

  // Handle download-trigger cards on download.html
  document.querySelectorAll('.download-trigger').forEach(card => {
    card.addEventListener('click', (event) => {
      event.preventDefault();
      const docName = card.dataset.documentName || 'Không xác định';
      window._currentDownloadDocument = docName;
      if (downloadModal) {
        downloadModal.classList.add('active');
        downloadResponse.textContent = '';
        downloadForm.reset();
      }
    });
  });

  downloadClose?.addEventListener('click', closeDownload);
  cancelDownload?.addEventListener('click', closeDownload);

  downloadModal?.addEventListener('click', (event) => {
    if (event.target === downloadModal) closeDownload();
  });

  signupForm?.addEventListener('submit', async (event) => {
    event.preventDefault();
    const formData = new FormData(signupForm);
    const name = sanitizeText(formData.get('name')?.toString() || '', 80);
    const email = sanitizeText(formData.get('email')?.toString() || '', 120);
    const phone = sanitizeText(formData.get('phone')?.toString() || '', 20);

    if (!name || name.length < 2 || !isValidEmail(email) || !isValidPhone(phone)) {
      signupResponse.textContent = 'Vui lòng nhập tên hợp lệ, email đúng định dạng và số điện thoại hợp lệ.';
      return;
    }

    // Hiển thị thông báo đang xử lý
    signupResponse.textContent = 'Đang xử lý...';

    try {
      // Thực sự gọi Supabase để insert dữ liệu vào bảng signups
      const { data, error } = await supabaseClient
        .from('signups')
        .insert([
          {
            name: name,
            email: email,
            phone: phone,
            created_at: new Date().toISOString()
          }
        ]);

      if (error) {
        console.error('Lỗi Supabase:', error);
        signupResponse.textContent = `Có lỗi xảy ra: ${error.message}. Vui lòng thử lại sau.`;
        return;
      }

      // Chỉ hiển thị thông báo thành công SAU KHI insert thành công
      signupResponse.textContent = 'Cảm ơn! Yêu cầu đăng ký của bạn đã được ghi nhận.';
      signupForm.reset();

      // Đóng modal sau 2.2 giây
      setTimeout(closeSignup, 2200);
    } catch (err) {
      console.error('Lỗi khi gửi dữ liệu:', err);
      signupResponse.textContent = 'Có lỗi xảy ra. Vui lòng kiểm tra kết nối internet và thử lại.';
    }
  });

  downloadForm?.addEventListener('submit', async (event) => {
    event.preventDefault();
    const formData = new FormData(downloadForm);
    const name = sanitizeText(formData.get('name')?.toString() || '', 80);
    const email = sanitizeText(formData.get('email')?.toString() || '', 120);
    const phone = sanitizeText(formData.get('phone')?.toString() || '', 20);

    if (!name || name.length < 2 || !isValidEmail(email) || !isValidPhone(phone)) {
      downloadResponse.textContent = 'Vui lòng nhập tên hợp lệ, email đúng định dạng và số điện thoại hợp lệ.';
      return;
    }

    // Show processing
    downloadResponse.textContent = 'Đang xử lý...';

    try {
      // Get current download document name
      const currentDownloadDocument = window._currentDownloadDocument || 'Không xác định';

      // Prepare download data
      const downloadData = {
        name: name,
        email: email,
        phone: phone,
        document_name: currentDownloadDocument
      };

      // Call Supabase to insert download record
      const { data, error } = await supabaseClient
        .from('downloads')
        .insert([downloadData]);

      if (error) {
        console.error('Lỗi Supabase:', error);
        downloadResponse.textContent = `Có lỗi xảy ra: ${error.message}. Vui lòng thử lại sau.`;
        return;
      }

      // Send confirmation email
      const emailTemplate = window.ResendEmailService?.getDownloadConfirmationTemplate({
        name: name,
        email: email,
        document_name: currentDownloadDocument
      });

      if (window.ResendEmailService && emailTemplate) {
        await window.ResendEmailService.sendEmail(
          email,
          `📥 Xác nhận tải tài liệu - ${currentDownloadDocument} | Mật Tông Việt`,
          emailTemplate
        ).catch(err => {
          console.warn('Email send warning:', err);
          // Continue even if email fails
        });
      }

      // Only show success message after Supabase insert succeeds
      downloadResponse.textContent = 'Tài liệu sẽ được gửi tới email của bạn ngay khi có thể.';
      downloadForm.reset();

      setTimeout(closeDownload, 2200);

    } catch (err) {
      console.error('Lỗi khi xử lý tải tài liệu:', err);
      downloadResponse.textContent = 'Có lỗi xảy ra. Vui lòng kiểm tra kết nối internet và thử lại.';
    }
  });

  if (downloadModal && window.location.pathname.endsWith('download.html')) {
    downloadModal.classList.add('active');
  }

  const isHomePage = document.getElementById('home') !== null;
  if (signupModal && isHomePage) {
    setTimeout(() => signupModal.classList.add('active'), 800);
  }
}).catch(()=>{});

/* Contact form handling (site-wide) */
const contactForm = document.getElementById('contactForm');
const contactResponse = document.getElementById('contactResponse');
const contactSuccess = document.getElementById('contactSuccess');
if (contactForm) {
  contactForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    const fd = new FormData(contactForm);
    const name = sanitizeText(fd.get('name') || '', 80);
    const email = sanitizeText(fd.get('email') || '', 120);
    const phone = sanitizeText(fd.get('phone') || '', 20);
    const subject = sanitizeText(fd.get('subject') || '', 100);
    const message = sanitizeText(fd.get('message') || '', 1000);

    if (!name || name.length < 2 || !isValidEmail(email) || !isValidPhone(phone) || message.length < 10) {
      if (contactResponse) {
        contactResponse.style.display = 'block';
        contactResponse.textContent = 'Vui lòng điền đầy đủ và đúng định dạng thông tin.';
      }
      return;
    }

    // Show processing indicator
    if (contactResponse) {
      contactResponse.style.display = 'block';
      contactResponse.textContent = 'Đang xử lý...';
    }
    contactForm.style.opacity = '0.6';
    contactForm.style.pointerEvents = 'none';

    try {
      // Prepare contact data for Supabase
      const contactData = {
        name: name,
        email: email,
        phone: phone,
        subject: subject,
        message: message
      };

      // Insert to Supabase
      const { data, error } = await supabaseClient
        .from('contacts')
        .insert([contactData]);

      if (error) {
        console.error('Supabase error:', error);
        if (contactResponse) {
          contactResponse.style.display = 'block';
          contactResponse.style.color = '#e74c3c';
          contactResponse.textContent = `Lỗi: ${error.message}. Vui lòng thử lại.`;
        }
        contactForm.style.opacity = '1';
        contactForm.style.pointerEvents = 'auto';
        return;
      }

      // Send confirmation email
      const emailTemplate = window.ResendEmailService?.getContactConfirmationTemplate({
        name: name,
        email: email,
        phone: phone,
        subject: subject
      });

      if (window.ResendEmailService && emailTemplate) {
        await window.ResendEmailService.sendEmail(
          email,
          `✉️ Xác nhận liên hệ - Mật Tông Việt`,
          emailTemplate
        ).catch(err => {
          console.warn('Email send warning:', err);
          // Continue even if email fails
        });
      }

      // Success: hide form, show success message
      contactForm.style.display = 'none';
      if (contactResponse) {
        contactResponse.style.display = 'none';
      }
      if (contactSuccess) {
        contactSuccess.style.display = 'block';
      }
      
      // Also save to localStorage as backup
      try {
        const leads = JSON.parse(localStorage.getItem('contact_leads') || '[]');
        leads.push({ name, email, phone, subject, message, ts: Date.now() });
        localStorage.setItem('contact_leads', JSON.stringify(leads));
      } catch (err) { /* ignore storage errors */ }

    } catch (err) {
      console.error('Contact form error:', err);
      if (contactResponse) {
        contactResponse.style.display = 'block';
        contactResponse.style.color = '#e74c3c';
        contactResponse.textContent = 'Lỗi kết nối. Vui lòng thử lại.';
      }
      contactForm.style.opacity = '1';
      contactForm.style.pointerEvents = 'auto';
    }
  });
}

/* Order form handling (checkout page) */
const orderForm = document.getElementById('orderForm');
const placeOrderBtn = document.getElementById('placeOrderBtn');
const orderSuccess = document.getElementById('orderSuccess');
const orderId = document.getElementById('orderId');
const successDetails = document.getElementById('successDetails');
const checkoutForm = document.getElementById('checkoutForm');

if (orderForm) {
  orderForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    const formData = new FormData(orderForm);
    
    // Collect order data
    const fullname = sanitizeText(formData.get('fullname') || '', 100);
    const email = sanitizeText(formData.get('email') || '', 120);
    const phone = sanitizeText(formData.get('phone') || '', 20);
    const address = sanitizeText(formData.get('address') || '', 200);
    const city = sanitizeText(formData.get('city') || '', 50);
    const district = sanitizeText(formData.get('district') || '', 50);
    const note = sanitizeText(formData.get('note') || '', 500);
    const payment = formData.get('payment') || 'cod';

    // Validate
    if (!fullname || fullname.length < 2 || !isValidEmail(email) || !isValidPhone(phone) || !address || !city) {
      if (placeOrderBtn) placeOrderBtn.textContent = 'Lỗi: Vui lòng điền đầy đủ thông tin bắt buộc';
      setTimeout(() => { placeOrderBtn.textContent = '✅ Đặt hàng'; }, 2000);
      return;
    }

    // Get cart
    const cart = getCart();
    if (!cart || cart.length === 0) {
      if (placeOrderBtn) placeOrderBtn.textContent = 'Lỗi: Giỏ hàng trống';
      setTimeout(() => { placeOrderBtn.textContent = '✅ Đặt hàng'; }, 2000);
      return;
    }

    // Calculate total
    const total = getCartTotal();

    // Generate order ID
    const newOrderId = generateOrderId();

    // Show processing message
    if (placeOrderBtn) placeOrderBtn.textContent = 'Đang xử lý đơn hàng...';
    if (placeOrderBtn) placeOrderBtn.disabled = true;

    try {
      // Prepare order data - match actual Supabase columns
      const orderData = {
        order_code: newOrderId,
        fullname: fullname,
        email: email,
        phone: phone,
        address: address || '',
        city: city || '',
        district: district || '',
        note: note || '',
        payment_method: payment || 'cod',
        total_amount: total
      };

      // Call Supabase to insert order
      const { data, error } = await supabaseClient
        .from('orders')
        .insert([orderData]);

      if (error) {
        console.error('Lỗi Supabase:', error);
        if (placeOrderBtn) placeOrderBtn.textContent = `❌ Lỗi: ${error.message}`;
        if (placeOrderBtn) placeOrderBtn.disabled = false;
        setTimeout(() => { 
          if (placeOrderBtn) placeOrderBtn.textContent = '✅ Đặt hàng'; 
        }, 3000);
        return;
      }

      try {
        const emailResponse = await fetch('/api/send-order-email', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            order_id: newOrderId,
            order_code: newOrderId,
            fullname,
            email,
            phone,
            address,
            city,
            district,
            note,
            payment_method: payment || 'cod',
            total_amount: total,
            items_json: JSON.stringify(cart),
            recipient_email: 'tamdang.digital@gmail.com'
          })
        });

        const emailResult = await emailResponse.json().catch(() => ({}));
        if (!emailResponse.ok) {
          console.warn('⚠️ Failed to send order email via API route:', emailResult);
        } else {
          console.log('✅ Order notification email request accepted:', emailResult);
        }
      } catch (emailError) {
        console.warn('⚠️ Order email request failed:', emailError);
      }

      // Order successfully inserted - show success page
      if (checkoutForm) checkoutForm.style.display = 'none';
      if (orderSuccess) orderSuccess.style.display = 'block';
      
      if (orderId) orderId.textContent = newOrderId;
      
      // Build success details
      if (successDetails) {
        let detailsHtml = '<div class="success-order-details">';
        detailsHtml += '<p><strong>Thông tin giao hàng:</strong></p>';
        detailsHtml += `<p>${fullname} | ${phone} | ${email}</p>`;
        detailsHtml += `<p>${address}, ${district ? district + ', ' : ''}${city}</p>`;
        if (note) detailsHtml += `<p><em>Ghi chú: ${escapeHtml(note)}</em></p>`;
        detailsHtml += '<p style="margin-top: 15px;"><strong>Phương thức thanh toán:</strong></p>';
        const paymentLabel = payment === 'cod' ? 'Thanh toán khi nhận hàng (COD)' : 
                            payment === 'bank' ? 'Chuyển khoản ngân hàng' : 'Ví MoMo / ZaloPay';
        detailsHtml += `<p>${paymentLabel}</p>`;
        detailsHtml += '<p style="margin-top: 15px;"><strong>Tổng tiền:</strong></p>';
        detailsHtml += `<p style="font-size: 18px; color: #d97706;">${formatVND(total)}</p>`;
        detailsHtml += '</div>';
        successDetails.innerHTML = detailsHtml;
      }

      // Clear cart
      clearCart();

      // Redirect after 5 seconds
      setTimeout(() => {
        window.location.href = 'index.html';
      }, 5000);

    } catch (err) {
      console.error('Lỗi khi xử lý đơn hàng:', err);
      if (placeOrderBtn) placeOrderBtn.textContent = '❌ Lỗi: Không thể xử lý đơn hàng';
      if (placeOrderBtn) placeOrderBtn.disabled = false;
      setTimeout(() => { 
        if (placeOrderBtn) placeOrderBtn.textContent = '✅ Đặt hàng'; 
      }, 3000);
    }
  });
}
